/** MIT. K130 own native structure plus documented visual reconstruction. */
import {THREE,materials,FACE,box,cylinder,hole,rectHole,solid,ring,roundedRect} from './geometry.js';
import {nativeParts,source} from './native-data.js';
import {spec} from './dimensions.js';
const plastic=c=>materials.plastic(c,{roughness:.77}),metal=c=>materials.metal(c,{roughness:.4}),tin=()=>metal(0xb5bab5),gold=()=>metal(0xb9a064);
function native(host){const root=new THREE.Group();root.rotation.y=Math.PI;root.name='K130 native own assembly rigid front-axis transform';host.body.add(root);const colors={'stamp-cover':0xff850a,'front-bezel':0xff850a,'inner-carrier':0x484c4c,'outer-rotor':0x666b6b,'threaded-rear-body':0x666b6a,'mounting-nut':0xff8608,'stamp-flange':0xff850a,'inner-retainer':0x555b57,'spacer-ring':0xb8b9ad},parts={};for(const d of nativeParts){const g=new THREE.BufferGeometry();for(const[name,values,Type,size]of[['position',d.positions,Float32Array,3],['normal',d.normals,Float32Array,3],['sourceFaceIndex',d.sourceFaceIndex,Uint32Array,1],['sourceAttributeWord',d.sourceAttributeWord,Uint16Array,1]])g.setAttribute(name,new THREE.BufferAttribute(new Type(values),size));g.setIndex(new THREE.BufferAttribute(new Uint16Array(d.indices),1));const o=new THREE.Mesh(g,plastic(colors[d.id]));o.name='K130 native '+d.id;o.userData={source:'official-structure',sourceFaceCount:d.triangles};root.add(o);parts[d.id]=o;}return{root,parts,source};}
function boards(host){const shape=hole(new THREE.Shape().absarc(0,0,20.6,0,Math.PI*2,false),0,0,6.7);for(const[x,y]of[[-12,0],[12,0]])hole(shape,x,y,1.15);for(const p of spec.grove)for(let i=0;i<4;i++)hole(shape,p.position[0],p.position[1]+(i-1.5)*2,.19);const pcb=solid(host.body,shape,.9,[0,0,-4.25],plastic(0x254738),'K130 own supported main PCB;actual annular encoder region and retained holes');const encoder=ring(host.body,16.4,13.9,4,[0,0,-3.3],tin(),'K130 EC30 supported encoder ring fixed stator'),encoderRotor=ring(host.body,13.6,11.8,3.7,[0,0,-3.15],plastic(0xd2d0c1),'K130 retained encoder moving sleeve'),lcdPCB=cylinder(host.body,17.2,.7,[0,0,13.8],plastic(0x315345),'K130 supported round display PCB'),lcdSupport=cylinder(host.body,17.4,1.1,[0,0,14.7],metal(0x666c67),'K130 real display module rear case'),glass=cylinder(host.body,17.8,.7,[0,0,16.55],materials.glossy(0x11171a,{roughness:.28}),'K130 supported full round cover glass physical thickness'),posts=[];for(let i=0;i<4;i++){const a=i*Math.PI/2+Math.PI/4;posts.push(cylinder(host.body,1.2,6.2,[18.6*Math.cos(a),18.6*Math.sin(a),-.1],plastic(0x5d655e),'K130 inferred fixed board post'));}const passives=[];for(const[x,y]of[[-14,8],[-11,12],[10,11],[14,-7],[8,-14],[-9,-14]])passives.push(box(host.body,[2.2,1.2,.8],[x,y,-4.65],plastic(0x8d917e),'K130 supported hidden component envelope'));const stampBoard=box(host.body,[17.8,23.6,.8],[0,-4.5,-5.95],plastic(0x2a4d3c),'K130 own StampS3 PCB envelope'),stampChip=box(host.body,[7,7,1.4],[0,1,-7.05],plastic(0x2d322f),'K130 original StampS3 ESP32-S3FN8 envelope'),antenna=box(host.body,[12.8,2.8,1.4],[0,5.4,-7.1],plastic(0xbab69f),'K130 own StampS3 antenna envelope'),labelSubstrate=solid(host.body,rectHole(roundedRect(16.6,22.2,.05),0,2,3.8,2.8),.05,[0,-4.5,-11.585],plastic(0xe5e5d9),'K130 supported label substrate on original native cover land;GPIO0 opening retained');labelSubstrate.userData.role='physical-label-substrate';return{pcb,encoder,encoderRotor,lcdPCB,lcdSupport,glass,posts,passives,stampBoard,stampChip,antenna,labelSubstrate};}
function grove(host,p){const frame=new THREE.Group();frame.position.fromArray(p.position);frame.quaternion.copy(FACE.back).multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,0,1),Math.PI/2));frame.name='K130 '+p.id+' vertical actual receiver';host.body.add(frame);const m=plastic(p.color),floor=box(frame,[10.1,.55,5.3],[0,-2.225,-2.65],m,'K130 Grove retained floor'),back=box(frame,[10.1,4.5,.55],[0,0,-5.025],m,'K130 Grove actual deep backstop'),walls=[-1,1].map(sign=>box(frame,[.55,5,5.3],[sign*4.775,0,-2.65],m,'K130 Grove actual sidewall')),bridge=box(frame,[4.8,.5,2.6],[0,2.25,-4],m,'K130 Grove partial keyed latch bridge'),contacts=[],tails=[],pads=[];for(const x of[-3,-1,1,3]){contacts.push(box(frame,[.32,.32,4.6],[x,.2,-2.9],tin(),'K130 actual Grove independent retained contact'));tails.push(cylinder(frame,.14,2.15,[x,.2,-6.1],tin(),'K130 Grove retained board tail'));pads.push(ring(frame,.38,.17,.04,[x,.2,-7.2],gold(),'K130 actual contact supporting land'));}return{frame,floor,back,walls,bridge,contacts,tails,pads};}
function usb(host){const frame=new THREE.Group();frame.position.fromArray(spec.usb.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const shape=roundedRect(8.4,3.2,1.5);shape.holes.push(roundedRect(7.9,2.7,1.25));const shell=solid(frame,shape,5.8,[0,0,-5.8],tin(),'K130 actual StampS3 USB-C thick metal shell'),stop=box(frame,[8.4,3.2,.3],[0,0,-5.95],plastic(0x232c29),'K130 USB-C deep physical stop'),tongue=box(frame,[6.2,.5,4.5],[0,0,-3.3],plastic(0x222b29),'K130 actual USB-C dielectric tongue'),contacts=[];for(const sign of[-1,1])for(let i=0;i<6;i++)contacts.push(box(frame,[.25,.055,4.2],[(i-2.5)*.9,sign*.278,-3.25],gold(),'K130 USB-C retained independent contact'));const seat=box(host.body,[8.7,5.5,.45],[0,-18.1,-5.2],plastic(0x294539),'K130 actual USB-C retained PCB end'),legs=[-1,1].map(s=>box(host.body,[.4,5,1.6],[s*4,-18.1,-6.2],tin(),'K130 USB-C retained board leg'));return{frame,shell,stop,tongue,contacts,seat,legs};}
function power(host){const frame=new THREE.Group();frame.position.set(0,17.6,-11.72);frame.quaternion.copy(FACE.back);host.body.add(frame);const shape=roundedRect(6.9,8.1,.25);for(const x of[-1.27,1.27])shape.holes.push(roundedRect(1.7,5.7,.12,{cx:x,cy:0,path:new THREE.Path()}));const shell=solid(frame,shape,5.5,[0,0,-5.5],plastic(0x15933a),'K130 green 2P input true independent keyed wells'),stops=[],contacts=[];for(const x of[-1.27,1.27]){stops.push(box(frame,[1.7,5.7,.3],[x,0,-5.65],plastic(0x175b2c),'K130 2P true physical stop'));contacts.push(box(frame,[.5,.5,4.7],[x,-.6,-3.15],tin(),'K130 retained 2.54mm supply contact'));}const battery=new THREE.Group();battery.position.set(8,-6,-5.2);host.body.add(battery);const sh=rectHole(roundedRect(4,3.2,.15),0,0,2.9,2.2);solid(battery,sh,3.3,[0,0,-3.3],plastic(0xdcd8c9),'K130 internal MX1.25 2P battery receiver,not a user exposed external port');box(battery,[4,3.2,.3],[0,0,-3.45],plastic(0x74776a),'K130 battery physical stop');for(const x of[-.625,.625])box(battery,[.22,.22,2.7],[x,0,-1.9],tin(),'K130 battery retained contact');return{frame,shell,stops,contacts,battery};}
function keys(host){const wakeSwitch=cylinder(host.body,3,1.2,[0,0,11.9],plastic(0x4d574f),'K130 inferred WAKE tactile package below round display'),wakeStem=cylinder(host.body,.8,1,[0,0,13],tin(),'K130 supported WAKE moving plunger'),bootHousing=box(host.body,[4.4,3.4,1.1],[0,-2.5,-9.8],plastic(0x555d50),'K130 supported StampS3 GPIO0 package'),bootCap=box(host.body,[3.5,2.4,.4],[0,-2.5,-11.85],plastic(0x1c2522),'K130 actual exposed StampS3 GPIO0 cap'),resetHousing=box(host.body,[3.5,3.5,1.2],[-13,-9.7,-8.8],plastic(0x5f665a),'K130 inferred reset switch below native elastic tongue'),screws=[];for(const x of[-12,12]){const shape=hole(new THREE.Shape().absarc(0,0,2.1,0,Math.PI*2,false),0,0,.85);screws.push(solid(host.body,shape,1.8,[x,0,-14.8],tin(),'K130 actual retained M2 screw head with recess'));screws.push(cylinder(host.body,.8,7,[x,0,-10.4],tin(),'K130 inferred retained screw shank'));screws.push(cylinder(host.body,.85,.15,[x,0,-13.05],metal(0x454b47),'K130 screw recess deep stop'));}return{wakeSwitch,wakeStem,bootHousing,bootCap,resetHousing,screws};}
export function buildAssembly(host){const n=native(host),b=boards(host),g=Object.fromEntries(spec.grove.map(p=>[p.id,grove(host,p)])),u=usb(host),p=power(host),k=keys(host);return{native:n,board:b,grove:g,usb:u,power:p,keys:k};}
